# Reescribe en textos.mjs los textos con cifras que cambian en la iteración del 8-nov-2026 (cifras de calc tal cual).
# Uso: python3 informes/enagas-2026-11-08/notas/reescribir-textos.py   (una sola vez; falla si no encuentra un texto)
import re, sys, os
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'textos.mjs')
s = open(P, encoding='utf-8').read()

def linea(prefijo, nuevo, final="',"):
    global s
    patron = re.compile(r'^(' + re.escape(prefijo) + r")(.*)$", re.M)
    m = [x for x in patron.finditer(s)]
    if len(m) != 1:
        sys.exit(f'{len(m)} coincidencias para {prefijo!r}')
    cola = prefijo.split("'", 1)[1] if "'" in prefijo else ''
    if cola and nuevo.startswith(cola):
        nuevo = nuevo[len(cola):]
    if "'" in nuevo:
        sys.exit('comilla simple en ' + prefijo)
    a, b = m[0].span()
    s = s[:a] + prefijo + nuevo + final + s[b:]

def asignacion(nombre, nuevo):
    linea(f"textos.{nombre} = '", nuevo, "';")

def bloque(inicio, fin, nuevo):
    global s
    i = s.index(inicio); j = s.index(fin, i) + len(fin)
    s = s[:i] + nuevo + s[j:]

